   "topic": "Appendicular, Upper Extremity",
   "competency": "a-42",
   "dok": 3,
   "stem": "The pectoral girdle attaches to the axial skeleton only at the small sternoclavicular joint, leaving the shoulder blade fairly free. Why does this loose attachment benefit the upper limb?",
