   "module": "m2",
   "topic": "Axial Skeleton, Spine",
   "competency": "a-40",
   "dok": 1,
   "term": "The vertebral foramen",
   "definition": "The vertebral foramen is the opening enclosed by the body and arch, through which the spinal cord runs.",
