   "module": "m2",
   "topic": "Axial Skeleton, Spine",
   "competency": "a-40",
   "dok": 1,
   "term": "The dens",
   "definition": "The dens, also called the odontoid process, is the upward bony peg of the axis that the atlas pivots around.",
