   "module": "m2",
   "topic": "Axial Skeleton, Spine",
   "competency": "a-41",
   "dok": 1,
   "term": "The manubrium",
   "definition": "The manubrium is the superior part of the sternum and articulates with the clavicles and the first ribs.",
