   "module": "m2",
   "topic": "Axial Skeleton, Spine",
   "competency": "a-40",
   "dok": 2,
   "term": "The intervertebral foramina",
   "definition": "The intervertebral foramina are the gaps between stacked vertebrae where the spinal nerves exit.",
