   "module": "m2",
   "topic": "Axial Skeleton, Spine",
   "competency": "a-26",
   "dok": 2,
   "term": "The sternal angle",
   "definition": "The sternal angle is the ridge where the manubrium meets the body of the sternum, a landmark level with the second rib.",
